[
  {
    "id": "must_take_cart",
    "text": "Customers should obtain a shopping cart before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "obtainCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "obtainCart"
    },
    "justification": "The rule refers to the general shopping practice of taking a cart rather than to any particular cart location or coordinate."
  },
  {
    "id": "no_exit_without_cart",
    "text": "Customers must not leave the store without their cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is about responsible cart use at store exit and does not depend on where the exit is located in a particular layout."
  },
  {
    "id": "cart_free_single_file_shelf_aisles",
    "text": "Customers must not push carts through single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The abstraction identifies narrow shelf aisles by local geometry and shelf adjacency, so it applies in any store with single-file aisles."
  },
  {
    "id": "no_enter_single_file_aisle_with_cart",
    "text": "Customers must not enter a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": "MOVE",
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterSingleFileShelfAisle"
        ]
      }
    },
    "justification": "The rule is based on entering locally narrow shelf space, not on the absolute position of that aisle in the demonstrated floor plan."
  },
  {
    "id": "park_cart_only_in_spacious_throughway",
    "text": "If a customer parks a cart, it should be left only in a spacious throughway rather than in a constrained passage.",
    "abstraction": {
      "state_properties": {
        "spaciousThroughway": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "spaciousThroughway"
          }
        ]
      }
    },
    "justification": "The norm uses local free-space measurements to characterize acceptable cart-staging areas instead of naming particular cells."
  },
  {
    "id": "do_not_park_cart_blocking_shelves",
    "text": "Customers must not park a cart directly beside shelves where it could block shelf access.",
    "abstraction": {
      "state_properties": {
        "shelfAccessZone": "adjShelf"
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          "shelfAccessZone"
        ]
      }
    },
    "justification": "The rule captures a general courtesy of not blocking merchandise shelves and is defined by shelf adjacency rather than coordinates."
  },
  {
    "id": "retrieve_parked_cart",
    "text": "A customer who parks a cart must retrieve it before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    },
    "justification": "The obligation concerns the general lifecycle of a borrowed cart and does not rely on where the cart was parked."
  },
  {
    "id": "retrieve_after_pedestrian_aisle",
    "text": "After leaving a cart-free single-file shelf aisle, the customer should retrieve their cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "leaveSingleFileShelfAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileShelfAisle"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileShelfAisle",
      "discharge": "retrieveCart"
    },
    "justification": "The trigger is defined by exiting a locally identified pedestrian-only shelf aisle, making the rule transferable across different store geometries."
  }
]

